'use strict';
// Offline product prototype. All mutations remain in memory. No network calls.
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge = (t,c='') => `<span class="badge ${c}">${esc(t)}</span>`;
const button = (t,a,id='',cls='') => `<button class="${cls}" data-a="${a}" data-id="${esc(id)}">${t}</button>`;
const link = (t,to,cls='') => `<a class="${cls}" href="#${to}">${t}</a>`;
const names = {draft:'等待分析',planned:'计划待开工',running:'执行中',review:'待交付审批',delivered:'已交付',failed:'异常待处理',rollback:'回滚进行中',recovered:'已恢复',cancelled:'已取消'};
const colors = {draft:'',planned:'amber',running:'amber',review:'amber',delivered:'green',failed:'red',rollback:'red',recovered:'blue',cancelled:''};
const closed = i => ['delivered','recovered','cancelled'].includes(i.stage);
const stages = ['已分配','工作中','候选已提交','队长已接受','独立复验中','复验通过'];
const repos = [
  {name:'order-service',desc:'订单、结账与价格审计',lang:'业务服务',team:'订单团队',mode:'托管原生',test:false,ready:true},
  {name:'admin-console',desc:'运营工作台与订单详情',lang:'管理界面',team:'运营界面团队',mode:'托管原生',test:false,ready:true},
  {name:'storefront',desc:'用户端商品与结账体验',lang:'用户界面',team:'交易体验团队',mode:'本地 CLI',test:false,ready:true},
  {name:'test-assets',desc:'跨仓场景、联调环境与证据',lang:'测试资产',team:'联调测试团队',mode:'本地 CLI',test:true,ready:true},
];
function makeIssue(id,title,stage,workspace='commerce'){
  return {id,title,stage,workspace,body:'在订单结账时记录价格被修改的原因，随订单保存，并在运营端订单详情展示。保留历史订单的正常读取行为。',policy:'key',paused:false,version:1,round:1,analysis:stage!=='draft',confirmed:stage!=='draft',plan:stage!=='draft',step:stage==='running'?1:['review','delivered','rollback','recovered'].includes(stage)?5:0,approved:stage==='delivered',mode:'托管原生',scope:{'order-service':'必改','admin-console':'必改','storefront':'待定','test-assets':'不做'},history:[],database:false};
}
const issues=[makeIssue('42','结账价格修改原因与审计记录','running'),makeIssue('41','订单部分退款后的金额一致性','review'),makeIssue('40','会员订单状态展示优化','delivered'),makeIssue('39','订单导出超时与中断恢复','failed'),makeIssue('38','新增支付失败的业务提示','planned'),makeIssue('12','内部知识检索体验改进','planned','internal')];
issues[1].database=true;
issues[5].scope={};
issues[5].body='改进内部资料的查找与阅读体验，权限范围按现有工作区授权。';
const state={workspace:'commerce',tab:'open',search:'',logged:true,draft:'',setup:0,localReady:false,roomTab:'chat',usageDays:7,logsView:'time',traceView:'session',logLevel:'',logSearch:'',chainSearch:'价格',chainMode:'semantic',chainId:'42',skill:'draft',skillPass:false,skillFailed:false,canaryPass:false,alertFiring:true,protect:'none',credential:false,accounts:['林悦 · 管理员','陈禾 · 项目审核人'],ruleSeq:2,rules:[{id:1,name:'模型高延迟',metric:'P95 延迟',threshold:20,active:true}],repoQuery:''};
const navs=[['issues','◎','需求'],['reviews','▣','审核台'],['repositories','▤','仓库'],['teams','♧','团队'],['agents','◇','智能体'],['observe','◴','观测'],['history','↶','历史决策']];
let toastTimer;
let modalReturn;
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function route(){return (location.hash.slice(1)||'issues').split('/')}
function current(){return issues.find(i=>i.id===route()[1])||issues[0]}
function selectedRepos(i){return repos.filter(r=>i.scope[r.name]==='必改')}
function pending(){return issues.filter(i=>i.workspace===state.workspace&&i.stage==='review'&&!i.approved)}
function go(to){if(location.hash==='#'+to)render();else location.hash=to}
function record(i,t){i.history.unshift({at:new Date().toLocaleTimeString('zh-CN',{hour12:false}),text:t})}
function head(title,desc='',actions=''){return `<div class="heading"><div><div class="eyebrow">REPOMESH / DELIVERY WORKSPACE</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></div>`}
function panel(title,body,actions='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><h2>${title}</h2><div class="actions">${actions}</div></div>${body}</section>`}
function metrics(items){return `<div class="metrics">${items.map(([label,value,note])=>`<div class="metric"><div class="label">${label}</div><div class="value">${value}</div><small>${note}</small></div>`).join('')}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function detail(k,v){return `<div class="detail-line"><span>${k}</span><span>${v}</span></div>`}
function empty(t,desc){return `<div class="empty"><strong>${esc(t)}</strong>${esc(desc)}</div>`}
function dialog(title,body,foot=''){
  modalReturn=document.activeElement;
  $('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2>${button('✕','close','','ghost small')}</div><div class="dialog-body">${body}<div id="form-error" class="form-error" role="alert"></div></div><div class="dialog-foot">${button('取消','close')}${foot}</div>`;
  $('#dialog').showModal();
}
function hide(){if($('#dialog').open)$('#dialog').close();if(modalReturn?.isConnected)modalReturn.focus()}
function fail(t){$('#form-error').textContent=t}
function render(){
  const [page,id,section]=route();
  if(!state.logged){$('#app').innerHTML=`<div class="login"><section class="login-card"><div class="logo"><span class="logo-mark">R</span> RepoMesh</div><div class="eyebrow">YOUR DELIVERY WORKSPACE</div><h1>让每次交付都有依据。</h1><p class="muted">登录你的协作工作台</p><label>用户名<input id="login-name" value="demo-reviewer" autocomplete="off"></label><label>演示密码<input type="password" value="prototype-demo" autocomplete="off"></label>${button('进入演示工作区','login','','primary')}${button('首次使用 · 初始化管理员','bootstrap','','ghost small')}<div class="notice">离线交互原型 · 任意非空名称均可进入，请勿输入真实凭证。</div></section></div>`;return}
  const active=page==='issue'||page==='room'?'issues':page==='usage'||page==='logs'||page==='trace'||page==='alerts'?'observe':page==='capabilities'||page==='operations'||page==='setup'?'settings':page;
  const wsName=state.workspace==='commerce'?'Commerce 团队':'Internal 团队';
  let content;
  if(page==='issues')content=issueList();else if(page==='issue')content=issuePage(current(),section||'overview');else if(page==='room')content=roomPage(current());else if(page==='reviews')content=reviewsPage();else if(page==='repositories')content=repoPage();else if(page==='teams')content=teamPage();else if(page==='agents')content=agentPage();else if(page==='observe')content=observePage();else if(page==='usage')content=usagePage();else if(page==='logs')content=logsPage();else if(page==='trace')content=tracePage();else if(page==='alerts')content=alertsPage();else if(page==='history')content=historyPage();else if(page==='settings')content=settingsPage();else if(page==='setup')content=setupPage();else if(page==='local')content=localPage();else if(page==='capabilities')content=capabilityPage();else if(page==='operations')content=opsPage();else content=guidePage();
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo"><span class="logo-mark">R</span> RepoMesh</div><div class="eyebrow">DELIVERY CONTROL</div><label class="muted">工作区<select id="workspace" aria-label="切换工作区"><option value="commerce" ${state.workspace==='commerce'?'selected':''}>Commerce 团队</option><option value="internal" ${state.workspace==='internal'?'selected':''}>Internal 团队</option></select></label>${button('＋ 新建需求','new','','primary')}<nav class="nav">${navs.map(([key,icon,title])=>link(`<span class="nav-icon">${icon}</span>${title}${key==='issues'?`<span class="count">${issues.filter(i=>i.workspace===state.workspace&&!closed(i)).length}</span>`:key==='reviews'?`<span class="count">${pending().length}</span>`:''}`,key,active===key?'active':'')).join('')}</nav><div class="sidebar-bottom"><nav class="nav">${link('<span class="nav-icon">⌘</span>本地智能体','local',active==='local'?'active':'')}${link('<span class="nav-icon">⚙</span>设置','settings',active==='settings'?'active':'')}${link('<span class="nav-icon">?</span>阅读指引','guide',active==='guide'?'active':'')}</nav><div class="identity"><div class="row"><span class="avatar">林</span><span><strong>林悦 · 演示管理员</strong><span class="muted">${wsName}</span></span></div>${button('退出演示','logout','','ghost small')}</div></div></aside><div class="workspace"><header class="topbar"><span>${esc(wsName)} <span class="muted">/ 产品工作台</span></span><span class="offline">● 离线演示 · 刷新重置 · 不执行真实操作</span></header><main>${content}<div class="footer-note">RepoMesh 产品原型 / 示例内容用于功能评审 · 保留现有视觉与需求中心结构</div></main></div></div>`;
}
function issueList(){
  let list=issues.filter(i=>i.workspace===state.workspace&&closed(i)===(state.tab==='closed')&&(!state.search||i.title.includes(state.search)||i.id.includes(state.search)));
  return head('需求','从一句需求，到经过验证的共同交付。',button('＋ 新建需求','new','','primary'))+metrics([['进行中的需求',issues.filter(i=>i.workspace===state.workspace&&!closed(i)).length,'按当前工作区统计'],['等待人工决定',pending().length,'每次决定绑定具体证据'],['参与仓库',state.workspace==='commerce'?repos.length:0,'长期资产与常设团队'],['本周已交付',issues.filter(i=>i.workspace===state.workspace&&i.stage==='delivered').length,'演示周期 · 最近 7 天']])+`<div class="toolbar"><div class="row">${button('◎ 未结束','tab-open','',state.tab==='open'?'primary':'')}${button('✓ 已结束','tab-closed','',state.tab==='closed'?'primary':'')}</div><div class="row"><input id="issue-search" aria-label="搜索需求" placeholder="搜索标题或需求编号" value="${esc(state.search)}">${button('搜索','search')}</div></div>`+(list.length?table(['需求','阶段','仓库','交付轮次',''],list.map(i=>`<tr><td><div class="issue-line"><span class="issue-dot ${closed(i)?'closed':''}"></span><div>${link(esc(i.title),'issue/'+i.id,'title')}<div class="subline">#${i.id} · 由组织负责人接收 · Commerce</div></div></div></td><td>${badge(names[i.stage],colors[i.stage])}${i.paused?' '+badge('已暂停','red'):''}</td><td>${selectedRepos(i).length} 仓</td><td>第 ${i.round} 轮</td><td>${link('查看 →','issue/'+i.id)}</td></tr>`)):empty('没有符合条件的需求','可以清除搜索，或新建一条需求。'));
}
function issuePage(i,section){
  if(i.workspace!==state.workspace)return head('需求不在当前工作区')+empty('当前范围不可见','切换到该需求所属工作区后再查看。');
  const tabs=[['overview','概览'],['discovery','发现与计划'],['execution','执行与房间'],['delivery','验证与交付'],['recovery','异常与恢复']];
  let body=section==='discovery'?discovery(i):section==='execution'?execution(i):section==='delivery'?delivery(i):section==='recovery'?recovery(i):overview(i);
  return link('← 所有需求','issues')+head(i.title,`#${i.id} · 计划 v${i.version} · 第 ${i.round} 轮 · ${selectedRepos(i).length} 个仓库`,`${badge(names[i.stage],colors[i.stage])}${i.paused?badge('已暂停','red'):''}${button('监管策略','policy',i.id)}${!closed(i)?button(i.paused?'恢复项目':'暂停项目','pause',i.id):''}`)+`<nav class="tabs">${tabs.map(([k,t])=>link(t,'issue/'+i.id+'/'+k,section===k?'active':'')).join('')}</nav>`+body;
}
function overview(i){
  return `<div class="grid2"><div>${panel('原始需求',`<p>${esc(i.body)}</p><div class="subline">需求来源：${esc(i.file||'直接输入')} · 规格版本 v${i.version}</div>`)}${panel('下一步',`<p>${i.stage==='draft'?'先分析需求，明确需要哪些仓库参与。':i.stage==='planned'?'计划已生成。检查团队就绪与监管策略，然后确认开工。':i.stage==='review'?'独立复验已通过，等待交付批准。':i.stage==='failed'?'一个执行成员中断，需要选择恢复动作。':closed(i)?'当前轮次已经结束，交付与历史证据可继续查看。':'团队正在按计划推进，你可以查看每个任务的尝试与证据。'}</p><div class="row">${link('发现与计划 →','issue/'+i.id+'/discovery')}${link('任务进度 →','issue/'+i.id+'/execution')}${link('交付证据 →','issue/'+i.id+'/delivery')}</div>`)}${panel('最近活动',`<div class="timeline">${[...i.history,{at:'10:42',text:'范围确认与任务判据已保留版本'},{at:'10:36',text:'组织负责人接收需求，开始分析'}].slice(0,5).map(h=>`<div class="event"><time>${esc(h.at)}</time><h3>${esc(h.text)}</h3></div>`).join('')}</div>`)}</div><div>${panel('工作安排',detail('组织负责人','Commerce Manager')+detail('执行方式',i.mode)+detail('监管方式',policyLabel(i.policy))+detail('当前计划','v'+i.version)+detail('审核人','陈禾 · 项目监督人'))}${panel('关联团队',selectedRepos(i).map(r=>`<div class="detail-line"><span>${esc(r.name)}</span>${link(esc(r.team),'room/'+i.id)}</div>`).join(''))}${panel('演示场景',`<p class="muted">切换此需求的演示状态，用于查看不同阶段的页面。</p><select id="scenario" aria-label="演示场景">${Object.entries(names).map(([k,v])=>`<option value="${k}" ${i.stage===k?'selected':''}>${v}</option>`).join('')}</select><div class="subline">仅修改当前需求的演示记录。</div>`)}</div></div>`;
}
function policyLabel(p){return {auto:'AI 自己干完',key:'关键处我看一眼',all:'每步都由我把关'}[p]}
function planGraph(i){let rs=selectedRepos(i);return `<div class="dag">${rs.map((r,n)=>`${n?'<div class="dag-arrow">→</div>':''}<div class="lane"><div class="lane-label">BATCH ${String(n+1).padStart(2,'0')}</div><div class="node ${i.step===5?'done':i.stage==='running'?'current':''}"><strong>${esc(r.name)}</strong><small>${esc(r.desc)}</small><hr><small>${i.step===5?'✓ 验证通过':n?'等待上游结果':'提供变更与业务约定'}</small></div></div>`).join('')}</div><div class="muted mono">${rs.length} 个批次 · ${Math.max(0,rs.length-1)} 条依赖 · 计划 v${i.version} · 只读预览</div>`}
function discovery(i){
  return `<div class="stepper">${['需求分析','候选评分','分档审批','生成计划'].map((x,n)=>`<div class="step ${i.plan?'done':i.confirmed&&n<3?'done':i.analysis&&n<2?'done':'on'}">0${n+1} ${x}</div>`).join('')}</div>`+
  (!i.analysis?panel('先明确业务边界',`<p>需要确认：历史订单是否需要补录？失败时用户看到什么提示？</p><label>补充说明<textarea id="clarification" placeholder="例如：历史订单无需补录，保留原有读取行为。"></textarea></label>`,`${button('忽略追问继续','force-analysis',i.id)}${button('补充并分析','analyze',i.id,'primary')}`):panel('需求分析已完成',`<p>目标：记录价格调整原因；范围约束：历史订单兼容；验收：原因可追溯、页面可查看。</p>${badge('来源：演示分析结果','blue')}`))+
  (i.analysis?panel('候选仓库与范围确认',table(['候选仓库','相关度','建议依据','最终分档'],repos.map((r,n)=>`<tr><td><strong>${esc(r.name)}</strong><div class="subline">${esc(r.desc)}</div></td><td class="nowrap">${[96,91,58,22][n]||50}%</td><td><details><summary>查看完整依据</summary>${n===0?'订单数据与价格调整能力直接相关，需要提供调整原因。':n===1?'使用订单信息展示详情，依赖订单服务提供的新信息。':'本次需求未明确要求该仓修改，需结合业务边界复核。'}<p class="muted">证据：已有仓库画像、职责摘要与依赖关系 · 演示</p></details></td><td><select data-scope="${esc(r.name)}" aria-label="${esc(r.name)} 最终分档" ${i.plan?'disabled':''}>${['必改','待定','不做'].map(t=>`<option ${i.scope[r.name]===t?'selected':''}>${t}</option>`).join('')}</select></td></tr>`))+`<label>范围意见<input id="scope-reason" placeholder="记录调整理由或附加条件"></label><p class="muted">人工调整与原始建议分别留存。排除必要依赖时须重新复核。</p>`,i.plan?button('调整范围并重规划','replan',i.id):i.confirmed?button('生成执行计划','generate-plan',i.id,'primary'):button('确认当前范围','confirm-scope',i.id,'primary')):'')+
  (i.plan?panel('执行计划 · 依赖与批次',planGraph(i)+`<div class="notice">开工前检查本轮团队、成员、验证能力和人工监管；计划预览不会派工。</div>`,`${button('追加工作预览','append',i.id)}${button('开工预览','start-preview',i.id,'primary')}`,'paper'):'');
}
function execution(i){
  return metrics([['当前任务阶段',stages[i.step],i.stage==='failed'?'成员中断，等待处理':'演示执行状态'],['参与成员',selectedRepos(i).length*2,'每仓 1 队长 + 1 执行成员'],['本轮尝试',i.round,'旧尝试保留'],['验证状态',i.step===5?'已通过':'待完成','初审与复验分别记录']])+panel('仓库任务',table(['仓库 / 任务','执行成员','阶段','证据'],selectedRepos(i).map((r,n)=>`<tr><td><strong>${esc(r.name)}</strong><div class="subline">${n?'展示业务变化并校验兼容':'完成业务能力及自测'}</div></td><td>Worker ${n+1}</td><td>${badge(i.stage==='failed'?'中断':stages[i.step],i.stage==='failed'?'red':i.step===5?'green':'amber')}</td><td>${button('查看','evidence',i.id,'small')}</td></tr>`)),button(i.step<5?'推进演示：'+stages[i.step+1]:'查看交付结果',i.step<5?'next':'go-delivery',i.id,'primary'))+
  panel('托管尝试时间线',`<div class="stepper">${stages.map((s,n)=>`<div class="step ${n<i.step?'done':n===i.step?'on':''}">${n<=i.step?'✓ ':''}${s}</div>`).join('')}</div><div class="notice">队长接受只表示候选可进入独立复验。只有复验通过才形成有效成果。</div>`)+
  panel('团队房间',selectedRepos(i).map(r=>`<div class="detail-line"><span>${esc(r.team)} · 团队房 / 负责人房</span>${link('打开房间 →','room/'+i.id)}</div>`).join(''));
}
function roomPage(i){return link('← 返回需求','issue/'+i.id+'/execution')+head('订单团队 · 协作房间',`${i.title} · 房间活动与正式任务状态分别显示`,badge(i.stage==='running'?'任务活动中':'暂无在途任务',i.stage==='running'?'amber':''))+`<div class="grid2"><div>${panel('房间视图',`<div class="tabs">${button('团队房','room-chat','',state.roomTab==='chat'?'active':'')}${button('负责人房','room-leader','',state.roomTab==='leader'?'active':'')}${button('任务图 · 计划 · 规格','room-plan','',state.roomTab==='plan'?'active':'')}</div>`+(state.roomTab==='plan'?planGraph(i):[['组','组织负责人','10:34','已冻结本轮范围与判据，请在获准范围内推进。'],['队','仓库队长','10:36',state.roomTab==='leader'?'收到仓库任务，审阅结论将按版本提交。':'任务已经指派，请提交变更清单和测试证据。'],['W','执行成员','10:42',i.step===5?'候选已通过独立复验，相关证据已关联。':'正在处理价格调整原因，历史订单兼容检查已列入。']].map(([a,n,t,msg])=>`<div class="message"><span class="avatar">${a}</span><div class="body"><strong>${n}</strong> <small>${t}</small><p>${msg}</p>${badge('结构化进度')}</div></div>`).join('')))}<div class="notice">沟通内容用于协作展示。正式变更请回到需求提交，聊天不直接扩大权限。</div></div><div>${panel('本仓工作环境',detail('仓库','order-service')+detail('工作方式',i.mode)+detail('当前尝试','第 '+i.round+' 次')+detail('候选状态',stages[i.step])+detail('所属交付组','需求 #'+i.id+' / 第 '+i.round+' 轮')+link('查看验证与交付 →','issue/'+i.id+'/delivery'))}</div></div>`}
function delivery(i){
  const verified=i.step===5;
  const approved=i.approved||i.policy==='auto';
  return metrics([['独立复验',verified?'通过':'未完成','固定当前候选版本'],['人工决定',approved?'已批准':'待批准',policyLabel(i.policy)],['交付仓库',selectedRepos(i).length,'按依赖顺序推进'],['当前轮次','0'+i.round,'历史轮次保留']])+
  panel('交付门禁',table(['条件','状态','说明'],[['独立复验',verified,'成员自测不替代独立验证'],['必需检查',verified,'与本轮候选一致'],['人工批准',approved,'变化后的候选需重新批准'],['依赖与冲突',i.stage!=='failed','上游完成后再推进下游'],...(i.database?[['数据环境验证',false,'外部环境未接入，保持阻塞']]:[])].map(([t,ok,d])=>`<tr><td>${t}</td><td>${badge(ok?'已满足':'阻塞',ok?'green':'red')}</td><td>${d}</td></tr>`)),`${button('浏览证据','evidence',i.id)}${i.stage==='delivered'?button('整组回滚预览','rollback-preview',i.id,'danger'):button('确认交付','deliver-preview',i.id,'primary')}`)+
  panel('候选与交付结果',table(['仓库','候选','验证','交付阶段'],selectedRepos(i).map((r,n)=>`<tr><td>${esc(r.name)}</td><td class="mono">候选 v${i.version}.${n+1}</td><td>${badge(verified?'已验证':'待验证',verified?'green':'')}</td><td>${badge(i.stage==='delivered'?'已确认合入':i.stage==='recovered'?'已恢复':i.stage==='rollback'?'反向评审中':verified?'候选待批准':'未发布',i.stage==='delivered'?'green':'')}</td></tr>`)))+
  (i.stage==='rollback'?panel('整组回滚进行中','<p>反向请求已形成，等待复验与确认。未合入候选将关闭，已完成部分按相反依赖顺序恢复。</p>',button('模拟复验并确认恢复','rollback-finish',i.id,'primary')):'')+
  panel('跨仓联调与数据验证',`<p>测试团队：test-assets · 固定组合：本轮 ${selectedRepos(i).length} 仓候选。</p>${detail('联调结果',verified?'通过 · 演示证据':'待执行')}${detail('环境',verified?'一次性环境已清理':'待准备')}<label class="inline"><input id="database-change" type="checkbox" ${i.database?'checked':''}>本任务声明涉及数据变更（演示）</label>${i.database?`<div class="notice">数据库测试交接 · 本块仅模拟产品状态，未连接真实数据服务。</div>${detail('受影响对象','订单价格调整记录')}${detail('必需检查','结构变化、历史数据兼容、业务读取')}${detail('测试交接','测试计划与当前候选绑定')}${detail('数据环境',badge('外部环境未接入','red'))}`:''}`)+
  panel('交付轮次',`<details open><summary>第 ${i.round} 轮 · 计划 v${i.version}</summary><p>${names[i.stage]} · ${selectedRepos(i).length} 个仓库 · ${i.approved?'已记录交付批准':'暂无本轮交付批准'}</p>${i.history.map(h=>`<p>${esc(h.at)} · ${esc(h.text)}</p>`).join('')}</details>${i.round>1?'<details><summary>第 1 轮 · 已被新轮次取代</summary><p>原候选、失败与旧确认保留，不再作为当前放行依据。</p></details>':''}`,button('导出演示证据摘要','export',i.id));
}
function recovery(i){return panel('当前恢复事项',i.stage==='failed'?`<div class="notice red">执行成员 Worker 1 中断 · 同一任务的旧尝试已封存</div>${detail('影响范围',esc(i.title)+' / order-service')}${detail('最后进展','已领取任务，候选尚未提交')}${detail('已尝试恢复','1 次 / 最多 3 次')}${detail('当前证据','版本 v'+i.version)}<p>可优先恢复原工作；原现场不可用时换给健康同队成员。</p>`:empty('当前没有未解决的异常','可在概览切换“异常待处理”场景查看恢复流程。'),i.stage==='failed'?button('选择恢复动作','recover-preview',i.id,'primary'):'')+panel('恢复记录',i.history.length?`<div class="timeline">${i.history.map(h=>`<div class="event"><time>${esc(h.at)}</time><p>${esc(h.text)}</p></div>`).join('')}</div>`:'<p class="muted">暂无恢复历史。失败和旧尝试会保留，不覆盖原记录。</p>')}
function reviewsPage(){const rows=pending();return head('审核台','只显示当前范围的待办。每份批准都绑定当时的证据。',badge(rows.length+' 项待处理','amber'))+(rows.length?table(['待审事项','检查点','版本','审核人',''],rows.map(i=>`<tr><td>${link(esc(i.title),'issue/'+i.id+'/delivery')}<div class="subline">#${i.id} · ${selectedRepos(i).length} 个仓库</div></td><td>交付批准</td><td>v${i.version}</td><td>陈禾</td><td>${button('打开审核','review',i.id,'primary small')}</td></tr>`)):empty('待办已清空','新的有效检查点到达时会出现在这里。'))+panel('审核原则','<p>可以批准、拒绝或要求修改。候选、范围或判据更新后，旧批准将失效。管理员身份与业务审批范围分别判断。</p>')}
function repoPage(){if(state.workspace!=='commerce')return head('仓库','当前工作区尚未接入仓库')+empty('暂无仓库','切换到 Commerce 工作区可查看仓库接入演示。');return head('仓库','资产长期存在，需求使用经过确认的仓库范围。',button('＋ 添加仓库','add-repo','','primary'))+`<div class="toolbar"><span class="muted">${repos.length} 个已登记仓库</span><div class="row"><input id="repo-query" aria-label="搜索仓库" placeholder="按仓库名称搜索" value="${esc(state.repoQuery)}">${button('搜索','repo-search')}</div></div>`+table(['仓库','画像','常设团队','工作方式','操作'],repos.filter(r=>r.name.includes(state.repoQuery)).map((r,n)=>`<tr><td><span class="title">${esc(r.name)}</span><div class="subline">${esc(r.lang)} · 最近扫描：今天</div></td><td>${esc(r.desc)}</td><td>${esc(r.team)} ${r.test?badge('跨仓联调','blue'):''}</td><td>${badge(r.mode,'amber')}</td><td><div class="row">${button('画像','repo-profile',String(repos.indexOf(r)),'small')}${button('团队档案','team-profile',String(repos.indexOf(r)),'small')}${button('验证','repo-verify',String(repos.indexOf(r)),'small')}</div></td></tr>`))+panel('扫描记录',detail('本次扫描',repos.length+' 个成功 · 0 个重复登记 · 0 个失败')+detail('来源','演示组织 · 全部扫描')+'<p class="muted">重新扫描将跳过已有登记并更新画像。失败时保留已有发现依据。</p>',button('整体重新扫描','rescan'))}
