function usagePage(){const m=state.usageDays===7?1:state.usageDays===30?4:11;return link('← 观测','observe')+head('用量大盘','窗口内的调用与估算费用；演示聚合不代表真实账单。',`<select id="usage-days" class="status-select" aria-label="统计窗口">${[7,30,90].map(d=>`<option value="${d}" ${state.usageDays===d?'selected':''}>最近 ${d} 天</option>`).join('')}</select>`)+metrics([['调用量',428*m,417*m+' 成功 / '+11*m+' 失败'],['模型消耗',(1.24*m).toFixed(2)+' M','输入与输出合计'],['估算费用','$ '+(4.82*m).toFixed(2),'按演示单价估算'],['平均延迟','6.8 s','P95 24.0 s']])+`<div class="grid2">${panel('每日调用趋势',`<div class="spark" aria-label="演示趋势柱状图">${[28,39,24,55,48,82,65,91,72,50,75,95,83,64].map(x=>`<i style="height:${x}%"></i>`).join('')}</div><div class="row between muted"><span>窗口开始</span><span>今天</span></div>`)}${panel('按模型',detail('规划模型','62% · $ '+(2.99*m).toFixed(2))+detail('执行模型','31% · $ '+(1.49*m).toFixed(2))+detail('验证摘要模型','7% · $ '+(.34*m).toFixed(2))+'<div class="notice">未记录消耗的调用应单列，不能估成零。</div>')}</div>`+panel('按需求归因',table(['需求','调用','费用','平均延迟'],issues.filter(i=>i.workspace===state.workspace).slice(0,4).map((i,n)=>`<tr><td>${link(esc(i.title),'issue/'+i.id)}</td><td>${[168,124,86,50][n]*m}</td><td>$ ${([1.86,1.4,1.02,.54][n]*m).toFixed(2)}</td><td>${[6.2,8.1,6.4,6.1][n]} s</td></tr>`)))+panel('发现步骤消耗',table(['步骤','调用','费用'],['需求分析','候选评分','三档分类','生成计划'].map((s,n)=>`<tr><td>${s}</td><td>${[84,96,68,180][n]*m}</td><td>$ ${([.92,1.08,.84,1.98][n]*m).toFixed(2)}</td></tr>`)))}
