function tracePage(){return link('← 观测','observe')+head('工作轨迹','可见活动记录与工具调用摘要，不代表所有内部推演。')+`<div class="tabs">${[['session','会话时间线'],['event','跨会话事件'],['issue','按需求']].map(([k,t])=>button(t,'trace-tab',k,state.traceView===k?'active':'')).join('')}</div>`+(state.traceView==='issue'?'<div class="notice">本示例按时间窗口近似关联，不能作为确定的因果归属。</div>':'')+panel(state.traceView==='event'?'工具与技能活动':'会话 #S-1042 · 订单团队',`<div class="timeline">${[['10:34:02','收到任务说明','输入：任务目标、仓库范围、固定判据','0.2 s'],['10:34:04','调用仓库查询工具','结果：发现价格调整能力与依赖','1.8 s'],['10:35:12','使用任务执行技能','版本 1.2.0 · 当前任务资料','38 s'],['10:36:04','运行独立验证','9 项检查通过 · 输出摘要已关联','4.2 s'],['10:36:10','提交候选结果','等待队长初审与平台核验','0.8 s']].map(([t,n,d,time])=>`<div class="event"><time>${t} · ${time}</time><h3>${n} ${badge('成功','green')}</h3><details><summary>查看事件摘要</summary>${d}<p class="muted">资料：规格 v1 · 关联需求 #42 · 示例内容</p></details></div>`).join('')}</div>`)}
function alertsPage(){return link('← 观测','observe')+head('告警','规则评估、活动事件和通知结果分别记录。',button('＋ 新建规则','new-rule','','primary'))+panel('阈值规则',table(['规则','指标与阈值','窗口','状态',''],state.rules.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.metric)} ＞ ${r.threshold}</td><td>15 分钟</td><td>${badge(r.active?'启用':'停用',r.active?'green':'')}</td><td><div class="row">${button(r.active?'停用':'启用','rule-toggle',r.id,'small')}${button('删除','rule-delete',r.id,'small')}</div></td></tr>`)),button('立即评估演示样本','evaluate'))+panel('触发历史',state.alertFiring?`<div class="notice red">模型高延迟 · 触发中 · 实际值 24 秒 / 阈值 20 秒</div>${detail('首次触发','10:47')}${detail('通知','未配置真实渠道')}${detail('保护动作',state.protect==='none'?'仅通知':state.protect==='pause'?'暂停新需求':'限制新的外部修改')}`:`${badge('已恢复','green')}<p>当前样本未触发启用规则；历史触发记录保留。</p>`)}
function historyPage(){let found=issues.filter(i=>i.workspace===state.workspace&&(state.chainMode==='id'?(i.title.includes(state.chainSearch)||i.id===state.chainSearch.replace('#','')):i.title.includes(state.chainSearch)||i.body.includes(state.chainSearch)));const i=found.find(x=>x.id===state.chainId)||found[0];return head('历史决策','谁决定了什么、为什么、哪些版本曾经生效。')+`<div class="toolbar"><div class="row"><select id="history-mode" class="status-select" aria-label="历史查找方式"><option value="semantic" ${state.chainMode==='semantic'?'selected':''}>自然语言检索 · 演示</option><option value="id" ${state.chainMode==='id'?'selected':''}>需求定位</option></select><input id="history-search" aria-label="查找历史决策" value="${esc(state.chainSearch)}" placeholder="价格 / 退款 / #42">${button('查找','history-search')}</div></div><p class="muted">离线检索使用示例文本匹配，真实语义检索属于正式产品能力。</p>`+(i?`<div class="row">${found.map(x=>button('#'+x.id+' '+esc(x.title),'history-select',x.id,x.id===i.id?'primary small':'small')).join('')}</div>`+panel(esc(i.title),`<p>${esc(i.body)}</p>${badge(names[i.stage],colors[i.stage])}<span class="mono muted"> · 需求 #${i.id} · 计划 v${i.version}</span>`)+`<div class="stepper">${['圈定范围','人工确认','执行顺序','拆成任务','提交交付'].map((s,n)=>`<a class="step ${n<4||i.stage==='delivered'?'done':''}" href="#history" data-a="chain-jump" data-id="${n}">${n+1}. ${s}</a>`).join('')}</div>`+[['圈定范围',selectedRepos(i).map(r=>r.name).join('、')+' 为必改仓库。依据：业务职责与已识别依赖。'],['人工确认','陈禾批准范围，附加条件：历史订单读取保持兼容。'],['安排执行顺序',i.id==='41'?'记录缺口：该历史步骤未留有效记录，不能从后续结果补写。':'订单服务先提供业务约定，运营界面随后使用。'],['拆成任务','逐仓形成任务，保留每个任务与指派记录。'],['提交交付',i.stage==='delivered'?'全部参与仓库已经确认合入。':'未到达最终交付，或当前仍待人工决定。']].map(([s,t],n)=>`<section id="chain-${n}">${panel(`${n+1}. ${s}`,`<p>${esc(t)}</p>${n<3?'<details><summary>版本记录 · 当前 v2 / 旧 v1</summary><p>v2 · 当前生效 · 已补充确认理由</p><p>v1 · 已被取代 · 原确认未附加说明</p></details>':''}<details><summary>溯源 · 原始事件与证据</summary><p>需求 #${i.id} · 计划 v${i.version} · 业务时间 10:36 · 记录时间 10:36</p><p>关联证据：范围、任务与本轮候选。演示记录。</p></details>`)}</section>`).join('')+panel('相似历史',issues.filter(x=>x.workspace===state.workspace&&x.id!==i.id).slice(0,2).map(x=>`<p>${button('#'+x.id+' '+esc(x.title),'history-select',x.id,'small')} ${badge('同仓历史参考')}</p>`).join('')):empty('未找到历史','尝试“价格”“退款”或“#42”。'))}
function settingsPage(){return head('设置','连接状态、人员授权和运营策略。',link('重新进入首次配置 →','setup'))+`<div class="grid2"><div>${panel('平台连接',detail('模型连接',badge(state.credential?'演示配置已保存':'示例已配置','green'))+detail('仓库授权',badge('示例已配置','green'))+detail('协作服务',badge('已就绪 · 演示','green'))+detail('独立复验',badge('已就绪 · 演示','green')),button('编辑演示连接','credentials'))}${panel('本地账户',state.accounts.map((a,n)=>detail('账户 '+(n+1),esc(a))).join(''),button('创建账户','account'))}</div><div>${link('<h2>能力管理</h2><p>技能版本、评估、试用与工具治理。</p>'+badge('补齐功能演示','amber'),'capabilities','card-link')}${link('<h2>运营管理</h2><p>容量保护、保留策略与恢复准备。</p>'+badge('补齐功能演示','amber'),'operations','card-link')}</div></div>`+panel('可用智能体工具',table(['工具','可见状态','能力说明'],['Claude Code','Codex','OpenCode','Cursor Agent','Copilot CLI','Aider','Goose'].map((n,k)=>`<tr><td>${n}</td><td>${badge(k<2?'示例已登记':'未探测',k<2?'green':'')}</td><td>是否安装、认证及支持恢复，应按实际环境验证</td></tr>`)))}
function setupPage(){const ss=['平台检测','模型连接','仓库授权','管理员账号','仓库与团队'];return head('首次使用配置','按步骤完成准备，已有进度可以保留。')+`<div class="stepper">${ss.map((s,n)=>`<div class="step ${n<state.setup?'done':n===state.setup?'on':''}">${n+1}. ${s}</div>`).join('')}</div>`+panel(ss[state.setup],[`${detail('基本服务',badge('就绪 · 演示','green'))}${detail('执行能力',badge('待本轮开工检查','amber'))}<p>本向导只示意用户准备流程，不安装或启动真实服务。</p>`,`<label>模型服务名称<input id="setup-model" value="规划与协作模型"></label><label>连接地址<input value="https://example.invalid/model" disabled></label><label>演示凭证<input type="password" value="demo-only" disabled></label>`,`<p>连接仓库托管服务，授权需要参与的组织与仓库。</p>${detail('授权应用','RepoMesh · 演示')}${detail('授权范围','Commerce 已登记仓库')}`,`${detail('当前管理员','林悦 · 演示账号')}${detail('审核人','陈禾 · 项目监督人')}<p>身份和项目权限分别配置。</p>`,`${detail('工作区','Commerce')}${detail('已登记仓库',repos.length+' 个')}${detail('团队编制',repos.length+' 支')}<p>完成向导后仍需对实际计划检查成员及验证能力。</p>`][state.setup],`${state.setup?button('上一步','setup-prev'):''}${button(state.setup===4?'进入工作区':'保存并继续','setup-next','','primary')}`)}
function localPage(){return head('本地智能体','确认成员真正到岗，再开始对应任务。',`${button('刷新状态','local-refresh')}${button('启动并检查','local-start','','primary')}${button('停止本地成员','local-stop','','danger')}`)+metrics([['启动器',state.localReady?'已连接':'未运行','演示本机状态'],['已就绪成员',state.localReady?'4 / 4':'0 / 4','真实任务就绪需独立检查'],['工作方式','本地 CLI','使用本机工具'],['适用宿主','Windows','现有一键启动范围']])+panel('逐成员状态',table(['成员','角色','本机状态','任务就绪','最后报告'],['交易队长','交易成员','测试队长','测试成员'].map((n,k)=>`<tr><td>${n}</td><td>${k%2?'执行成员':'仓库队长'}</td><td>${badge(state.localReady?'运行中':'未启动',state.localReady?'green':'')}</td><td>${badge(state.localReady?'就绪':'未连接',state.localReady?'green':'red')}</td><td>${state.localReady?'刚刚':'暂无'}</td></tr>`)))+panel('启动器不可用时','<p>使用平台提供的固定启动指引，在本机启动已登记成员后回到此页检查。</p><div class="notice">本原型不会启动任何本机进程；点击按钮只切换演示状态。</div>',button('查看准备清单','local-guide'))}
function capabilityPage(){const labels={draft:'草稿',evaluating:'评估中',canary:'小范围试用',promoted:'正式发布',rolled_back:'已撤回'};return link('← 设置','settings')+head('能力管理','技能发布有证据，任务使用有版本。',badge('补齐功能 · 演示','amber'))+panel('任务执行技能 · v1.3.0',detail('当前状态',badge(labels[state.skill],state.skill==='promoted'?'green':'amber'))+detail('评估',state.skillPass?'已通过正常与失败场景评估':'暂无合格评估')+detail('试用证据',state.canaryPass?'试用工作区评估通过':'尚未获得')+detail('试用范围','Commerce 演示工作区')+`<div class="row">${button('登记合格评估','skill-pass')}${button('登记失败评估','skill-fail','','danger')}${button('推进下一阶段','skill-next','','primary')}${button('撤回版本','skill-rollback','','danger')}</div>`)+panel('角色能力组合',table(['角色','技能','资料范围'],[['组织负责人','需求接收、跨仓规划、交付治理','组织及项目共享资料'],['仓库队长','任务拆分、结果评估、问题升级','本仓与授权项目资料'],['执行成员','任务执行、自测、结果回报','当前任务所需资料'],['测试团队','跨仓联调、证据整理','固定组合和验收判据']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`)))+panel('工具治理',detail('仓库服务','30 秒超时 · 仅允许安全读取重试')+detail('资料查询','20 秒超时 · 降级后阻止新修改')+detail('浏览验证','60 秒超时 · 连续超时进入降级')+'<p class="muted">上述为现有策略的产品呈现示意，未连接真实外部工具。</p>')}
function opsPage(){return link('← 设置','settings')+head('运营管理','容量、保护与恢复依据在同一处可见。',badge('补齐功能 · 演示','amber'))+metrics([['排队执行','12 / 40','可用 · 演示计数'],['活跃成员','8 / 10','承压 · 80%'],['待交付事项','—','实际容量来源未接入'],['最近恢复演练','未提供','不能判定已具备恢复能力']])+panel('告警保护策略',`<label>当前自动动作<select id="protection"><option value="none" ${state.protect==='none'?'selected':''}>仅通知</option><option value="pause" ${state.protect==='pause'?'selected':''}>暂停新需求</option><option value="writes" ${state.protect==='writes'?'selected':''}>限制新的外部修改</option></select></label><p class="muted">只作用于新工作，不自动停止成员、合入或回滚。</p>`,button('保存演示策略','ops-save','','primary'))+panel('保留与恢复准备',detail('普通日志保留','30 天 · 演示值')+detail('轨迹与消耗保留','90 天 · 演示值')+detail('业务审计与交付证据','不在普通日志清理范围')+detail('最近备份',badge('外部能力未接入','red'))+detail('恢复演练',badge('缺少证据','red'))+detail('可升级结论',badge('待准备','amber')))}
function guidePage(){return head('阅读指引','完整功能见 PRD 分册；本页提供主要演示路线与历史对照。')+panel('推荐走查路径','<p>新建需求 → 发现与计划 → 配置监管 → 开工预览 → 执行与房间 → 验证与交付 → 审核台 → 交付 → 整组回滚。</p><p>异常演示：打开需求 #39 的异常与恢复。数据交接演示：打开需求 #41 的验证与交付。技能与运营演示：从设置进入。</p><div class="notice">所有动作只改变本页内存。刷新将重置；文档实际导入仅支持文本与 Markdown，其他格式见 PRD 要求。</div>')+panel('原有原型提取',`<p><a href="历史原型/需求中心.html">需求中心原型 ↗</a></p><p><a href="历史原型/发现计划回滚.html">发现、计划与回滚原型 ↗</a></p><p><a href="历史原型/历史决策.html">历史决策原型 ↗</a></p><p><a href="历史原型/观测中心.html">观测中心原型 ↗</a></p><p class="muted">历史副本用于对照，不代表现行完整功能。统一原型保留需求中心结构和配色，并补上后续功能入口。</p>`)+panel('扩展能力 · 仓库内入口','<div class="stepper"><div class="step on">1. 提及助手规划</div><div class="step on">2. 确认指定范围</div><div class="step on">3. 显式要求执行</div><div class="step on">4. 回写交付状态</div></div><p>首期以 GitHub 议题为入口；最终范围仍可涉及多个获准仓库。普通提问不会直接触发执行。真实外部入口、企业身份和生产发布均不在本离线原型中执行。</p>')}
const value=(id)=>document.getElementById(id)?.value?.trim()||'';
function showNew(){
  if(state.protect==='pause'){notify('演示运营策略已暂停新需求，请先到运营管理解除。');return}
  dialog('新建需求',`<p class="muted">处理者：当前工作区组织负责人</p><label>需求标题<input id="new-title" placeholder="用一句话概括需要解决的问题" value="${esc(state.draftTitle||'')}"></label><label>目标、约束与预期结果<textarea id="new-body" placeholder="告诉团队要交付什么…">${esc(state.draft)}</textarea></label><label>导入文本需求<input id="new-file" type="file" accept=".txt,.md,.markdown"></label><p id="file-note" class="muted">离线导入支持文本与 Markdown。完整文档格式见 PRD。</p>`,button('创建需求','create','','primary'));
}
function policyDialog(i){dialog('监管策略',`<p>首次开工前明确哪些地方需要等待人。</p>${[['auto','AI 自己干完','不设常规人工卡点，交付验证与授权仍有效。'],['key','关键处我看一眼','仓库范围、交付需要确认，异常时升级。'],['all','每步都由我把关','六类检查点全部生效，执行按任务逐次确认。']].map(([k,t,d])=>`<label class="choice"><input type="radio" name="policy" value="${k}" ${i.policy===k?'checked':''}>${t}<small>${d}</small></label>`).join('')}<label>审核人<select id="reviewer"><option>陈禾 · 项目监督人</option><option>林悦 · 项目监督人</option></select></label><div class="checklist">${['仓库范围','规格','任务执行','验证','交付','异常升级'].map(t=>`<span>${badge(t)}</span>`).join('')}</div><div class="notice">本原型演示三档预设。精细授权和在途策略变更按 PRD 单独评审。</div>`,button('保存策略','policy-save',i.id,'primary'))}
function startDialog(i){const rs=selectedRepos(i);dialog('确认本轮开工',`<p>计划 v${i.version} · ${rs.length} 个仓库 · ${rs.length} 个成员任务</p>${table(['仓库','团队','方式'],rs.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.team)}</td><td>${esc(i.mode)}</td></tr>`))}<label>本轮工作方式<select id="start-mode"><option ${i.mode==='托管原生'?'selected':''}>托管原生</option><option ${i.mode==='本地 CLI'?'selected':''}>本地 CLI</option></select></label>${detail('监管策略',policyLabel(i.policy))}${detail('范围确认',i.confirmed?'当前版本已确认':'缺少确认')}${detail('独立验证能力','就绪 · 演示')}${detail('本地成员',state.localReady?'4 / 4 就绪':'未启动，仅影响本地方式')}<div class="notice">会建立本轮任务并通知团队。未就绪条件不允许越过；重复确认不会重复开工。</div>`,button('确认开工','start',i.id,'primary'))}
function evidenceDialog(i){dialog('当前候选与验证证据',`${detail('需求',esc(i.title))}${detail('计划与轮次','v'+i.version+' / 第 '+i.round+' 轮')}${detail('成员自测',i.step>=2?'已提交':'待提交')}${detail('队长审阅',i.step>=3?'接受':'待处理')}${detail('独立复验',i.step===5?'通过':'未完成')}${detail('候选组合',selectedRepos(i).map(r=>esc(r.name)).join('、'))}<details open><summary>必需检查结果</summary><p>调整原因可记录 · 历史订单兼容 · 运营详情显示</p><p>${i.step===5?'演示结果：9 项通过、0 项失败。':'目前没有有效的独立复验完成记录。'}</p></details><div class="notice">这是演示证据。正式产品需保留实际步骤、结果、摘要与请求标识。</div>`,button('查看需求交付','modal-delivery',i.id,'primary'))}
function reviewDialog(i){dialog('处理交付审核',`${detail('需求',esc(i.title))}${detail('证据版本','v'+i.version)}${detail('独立复验',i.step===5?'已通过':'未完成')}<p>批准只对当前候选、范围和证据有效。</p><label>决定<select id="review-result"><option value="approve">批准</option><option value="changes">要求修改</option><option value="reject">拒绝</option></select></label><label>审核理由<textarea id="review-reason" placeholder="记录依据或需要修改的事项"></textarea></label>`,button('提交决定','review-save',i.id,'primary'))}
function rollbackDialog(i){dialog('回滚整个交付组',table(['仓库','当前状态','对应动作'],[...selectedRepos(i)].reverse().map((r,n)=>`<tr><td>${esc(r.name)}</td><td>已确认合入</td><td>第 ${n+1} 步：形成反向评审请求</td></tr>`))+`<label>回滚原因<textarea id="rollback-reason" placeholder="说明需要恢复的业务原因"></textarea></label><label class="inline"><input type="checkbox" id="rollback-confirm">我已核对整组范围及逆序恢复要求</label><div class="notice">确认后开始受控恢复。反向变更仍需验证与审核，发生冲突会产生修复事项。</div>`,button('开始整组回滚','rollback',i.id,'danger'))}
async function act(a,id){
  const i=issues.find(x=>x.id===id)||current();
  switch(a){
    case 'close':hide();return;
    case 'new':showNew();return;
    case 'create':{
      const title=value('new-title'),body=value('new-body');
      if(!title||!body){fail('请填写标题和需求内容。');return}
      const item=makeIssue(String(Math.max(...issues.map(x=>Number(x.id)))+1),title,'draft',state.workspace);item.body=body;item.file=state.draftFile;issues.unshift(item);state.draft='';state.draftTitle='';state.draftFile='';state.tab='open';hide();go('issue/'+item.id+'/discovery');notify('需求已创建 · 演示');return;
    }
    case 'tab-open':state.tab='open';break;
    case 'tab-closed':state.tab='closed';break;
    case 'search':state.search=value('issue-search');break;
    case 'logout':state.logged=false;break;
    case 'login':if(!value('login-name')){notify('请填写一个演示名称。');return}state.logged=true;break;
    case 'bootstrap':state.logged=true;state.setup=0;go('setup');return;
    case 'policy':policyDialog(i);return;
    case 'policy-save':i.policy=$('input[name="policy"]:checked').value;record(i,'监管策略设为：'+policyLabel(i.policy));hide();break;
    case 'pause':if(i.stage==='cancelled'){notify('已取消需求不能恢复。');return}dialog(i.paused?'恢复项目':'暂停项目',`<p>${i.paused?'恢复后允许继续分配与执行。':'暂停会阻止后续分配与新执行，已经产生的交付需要单独处理。'}</p>`,button('确认','pause-confirm',i.id,'primary'));return;
    case 'pause-confirm':i.paused=!i.paused;record(i,i.paused?'人工暂停项目':'人工恢复项目');hide();break;
    case 'analyze':if(!value('clarification')){notify('请补充说明，或选择忽略追问继续。');return}i.body+='\n补充：'+value('clarification');i.analysis=true;record(i,'补充澄清后完成分析');break;
    case 'force-analysis':dialog('忽略追问继续',`<p>尚有 2 项澄清未回答。继续后会在历史中记录忽略情况。</p>`,button('确认并留痕','force-confirm',i.id,'primary'));return;
    case 'force-confirm':i.analysis=true;record(i,'忽略 2 条追问继续分析');hide();break;
    case 'confirm-scope':if(!selectedRepos(i).length){notify('至少选择一个必改仓库。');return}if(i.scope['admin-console']==='必改'&&i.scope['order-service']!=='必改'){notify('运营界面依赖订单服务，请复核必改范围。');return}i.confirmed=true;record(i,'陈禾确认范围：'+(value('scope-reason')||'采用当前分档'));break;
    case 'generate-plan':if(!i.confirmed){notify('请先确认范围。');return}i.plan=true;i.stage='planned';record(i,'生成执行计划 v'+i.version);break;
    case 'replan':dialog('调整范围并重新规划','<p>当前计划将保留为历史，新范围需要再次确认。原批准不用于新候选。</p>',button('建立新版本','replan-confirm',i.id,'primary'));return;
    case 'replan-confirm':i.version++;i.round++;i.confirmed=false;i.plan=false;i.approved=false;i.stage='draft';i.analysis=true;i.step=0;record(i,'建立新范围版本，原计划保留');hide();break;
    case 'append':dialog('追加工作预览',`<p>只允许加入当前计划尚未包含的仓库。已执行工作保持原样。</p><label>新增仓库<select id="append-repo">${repos.filter(r=>i.scope[r.name]!=='必改').map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></label><label>追加原因<input id="append-reason" placeholder="说明新增工作的必要性"></label><div class="notice">新增范围需要重新确认，并进入后续批次。</div>`,button('确认范围并追加','append-save',i.id,'primary'));return;
    case 'append-save':if(['delivered','failed','cancelled','recovered'].includes(i.stage)){fail('已结束或失败的计划不能追加，请建立新计划。');return}if(!value('append-repo')||!value('append-reason')){fail('请选择仓库并填写原因。');return}i.scope[value('append-repo')]='必改';i.version++;i.approved=false;record(i,'人工批准新增范围：'+value('append-repo')+'；'+value('append-reason'));hide();break;
    case 'start-preview':startDialog(i);return;
    case 'start':{
      if(i.paused){fail('项目已暂停，请先恢复。');return}
      if(i.stage!=='planned'){fail('本轮已经开工或计划尚未就绪，不能重复创建。');return}
      const mode=value('start-mode');if(mode==='本地 CLI'&&!state.localReady){fail('本地成员未就绪。请关闭弹窗，到“本地智能体”启动并检查。');return}
      i.mode=mode;i.stage='running';i.step=0;record(i,'计划 v'+i.version+' 开工，方式：'+mode);hide();go('issue/'+i.id+'/execution');return;
    }
    case 'next':if(i.paused||i.stage!=='running'){notify('当前不是可推进的执行状态，请先开工、恢复或处理异常。');return}i.step=Math.min(5,i.step+1);record(i,stages[i.step]);if(i.step===5)i.stage='review';break;
    case 'go-delivery':go('issue/'+i.id+'/delivery');return;
    case 'modal-delivery':hide();go('issue/'+i.id+'/delivery');return;
    case 'evidence':evidenceDialog(i);return;
    case 'review':reviewDialog(i);return;
    case 'review-save':{
      if(i.stage!=='review'||i.approved){fail('当前审核已失效或已被处理。');return}
      const reason=value('review-reason');if(!reason){fail('请填写审核理由。');return}const result=value('review-result');record(i,'陈禾：'+({approve:'批准',changes:'要求修改',reject:'拒绝'}[result])+'；'+reason);
      if(result==='approve')i.approved=true;else if(result==='changes'){i.version++;i.round++;i.approved=false;i.stage='running';i.step=1;}else{i.stage='failed';i.approved=false;}hide();notify('决定已记录 · 演示');break;
    }
    case 'deliver-preview':dialog('核对本轮交付',`${detail('需求',esc(i.title))}${detail('候选版本','v'+i.version)}${detail('参与仓库',selectedRepos(i).map(r=>esc(r.name)).join('、'))}<p>将按计划依赖顺序推进。等待外部确认期间不会视为已完成。</p>`,button('确认并演示交付','deliver',i.id,'primary'));return;
    case 'deliver':if(i.paused||i.step!==5||(!i.approved&&i.policy!=='auto')||i.stage==='failed'||i.stage==='cancelled'){fail('门禁未满足：需独立复验、有效人工批准，且项目可继续。');return}if(i.database){fail('本任务的数据验证环境未接入，不能交付。请保留为外部阻塞示例。');return}if(state.protect==='writes'){fail('运营策略限制新的外部修改，请先处理活动保护。');return}i.stage='delivered';record(i,'各仓按依赖顺序完成交付，结果已确认 · 演示');hide();break;
    case 'rollback-preview':rollbackDialog(i);return;
    case 'rollback':if(!value('rollback-reason')||!$('#rollback-confirm').checked){fail('请填写回滚原因，并核对整组范围。');return}i.stage='rollback';record(i,'开始整组逆序恢复：'+value('rollback-reason'));hide();break;
    case 'rollback-finish':i.stage='recovered';record(i,'反向变更通过复验，整组恢复已确认 · 演示');break;
    case 'recover-preview':dialog('选择恢复动作',`<p>旧尝试已经中断。决定绑定当前证据 v${i.version}。</p><label>恢复方式<select id="recover-action"><option>恢复原会话</option><option>重新开始本任务</option><option>更换健康同队成员</option><option>请求人工处理</option><option>取消任务</option></select></label><label>原因<textarea id="recover-reason" placeholder="说明所选动作的依据"></textarea></label>`,button('确认恢复决定','recover',i.id,'primary'));return;
    case 'recover':if(!value('recover-reason')){fail('请填写恢复依据。');return}record(i,value('recover-action')+'：'+value('recover-reason'));if(value('recover-action')==='取消任务')i.stage='cancelled';else if(value('recover-action')!=='请求人工处理'){i.round++;i.version++;i.step=1;i.stage='running';i.approved=false;}hide();break;
    case 'export':{const data=['RepoMesh 演示证据摘要',i.title,'计划 v'+i.version,'阶段：'+names[i.stage],...i.history.map(h=>h.at+' '+h.text),'本文件为离线演示，不是真实交付证明。'].join('\n');const blob=URL.createObjectURL(new Blob([data],{type:'text/plain;charset=utf-8'}));const el=document.createElement('a');el.href=blob;el.download='RepoMesh-demo-'+i.id+'.txt';el.click();setTimeout(()=>URL.revokeObjectURL(blob),1000);notify('演示摘要已生成');return}
    case 'room-chat':state.roomTab='chat';break;
    case 'room-leader':state.roomTab='leader';break;
    case 'room-plan':state.roomTab='plan';break;
    case 'repo-search':state.repoQuery=value('repo-query');break;
    case 'add-repo':dialog('添加仓库',`<label>仓库地址<input id="repo-url" placeholder="https://example.invalid/team/repository"></label><label>业务职责<input id="repo-desc" placeholder="例如：订单管理与业务审计"></label><div class="notice">仅解析演示地址，不访问远程服务。授权由平台连接统一管理。</div>`,button('模拟扫描并登记','repo-save','','primary'));return;
    case 'repo-save':{let url;try{url=new URL(value('repo-url'))}catch{fail('请输入完整的仓库地址。');return}if(!['https:','http:'].includes(url.protocol)){fail('请使用网页仓库地址。');return}const name=url.pathname.split('/').filter(Boolean).pop();if(!name){fail('地址中缺少仓库名称。');return}if(repos.some(r=>r.name===name)){fail('该仓库已登记，整体重扫不会重复创建。');return}repos.push({name,desc:value('repo-desc')||'待完善画像',lang:'新接入',team:name+' 团队',mode:'托管原生',test:false,ready:true});hide();notify('演示扫描完成：登记 1 仓，新增 1 份画像。');break}
    case 'rescan':dialog('整体重新扫描',`<p>扫描范围：${repos.length} 个已登记仓库。会更新画像，跳过重复登记。</p>`,button('完成本次演示扫描','rescan-done','','primary'));return;
    case 'rescan-done':hide();notify('演示扫描完成：'+repos.length+' 个更新，0 个重复登记。');return;
    case 'repo-profile':{const r=repos[Number(id)];dialog('仓库画像 · '+r.name,detail('职责',esc(r.desc))+detail('画像版本','v3 · 演示')+detail('发现来源','职责摘要、依赖关系及历史确认')+'<p>关联需求：价格审计、订单退款与状态展示。</p>');return}
    case 'team-profile':{const r=repos[Number(id)];dialog('团队档案 · '+r.name,`<p>${esc(r.team)} · 1 位队长，1 位执行成员</p><label>工作方式<select id="team-mode"><option ${r.mode==='托管原生'?'selected':''}>托管原生</option><option ${r.mode==='本地 CLI'?'selected':''}>本地 CLI</option></select></label><label class="inline"><input id="test-team" type="checkbox" ${r.test?'checked':''}>提供跨仓联调能力</label><div class="notice">档案开关只影响后续新编制。有活跃任务时不允许更换工作方式。</div>`,button('保存档案','team-save',id,'primary'));return}
    case 'team-save':{const r=repos[Number(id)];const mode=value('team-mode');if(mode!==r.mode&&issues.some(x=>x.stage==='running'&&x.scope[r.name]==='必改')){fail('该团队有活跃任务，先完成或取消在途工作后再切换。');return}r.mode=mode;r.test=$('#test-team').checked;hide();break}
    case 'repo-verify':{const r=repos[Number(id)];dialog('仓库验证配置 · '+r.name,`<label>必需检查<textarea id="repo-checks">${esc(r.checks||'业务行为检查\n历史兼容检查')}</textarea></label><label>允许的测试范围<input id="repo-test-scope" value="${esc(r.testScope||'本仓测试资产')}"></label>`,button('保存配置','verify-save',id,'primary'));return}
    case 'verify-save':if(!value('repo-checks')||!value('repo-test-scope')){fail('请填写必需检查和测试范围。');return}repos[Number(id)].checks=value('repo-checks');repos[Number(id)].testScope=value('repo-test-scope');hide();notify('验证配置已保存 · 演示');break;
    case 'logs-time':state.logsView='time';break;
    case 'logs-group':state.logsView='group';break;
    case 'logs-drill':state.logsView='time';state.logSearch=id;state.logLevel='';break;
    case 'logs-filter':state.logLevel=value('log-level');state.logSearch=value('log-search');break;
    case 'logs-clear':state.logLevel='';state.logSearch='';break;
    case 'trace-tab':state.traceView=id;break;
    case 'new-rule':dialog('新建告警规则',`<label>规则名称<input id="rule-name" placeholder="例如：模型高延迟"></label><label>指标<select id="rule-metric"><option>P95 延迟</option><option>错误数</option><option>费用</option><option>调用量</option></select></label><label>大于阈值<input id="rule-threshold" type="number" min="0.01" step="any" value="20"></label><p class="muted">观察窗口：15 分钟，按演示样本评估。</p>`,button('保存规则','rule-save','','primary'));return;
    case 'rule-save':if(!value('rule-name')||!Number.isFinite(Number(value('rule-threshold')))||Number(value('rule-threshold'))<=0){fail('请填写名称和大于零的阈值。');return}state.rules.push({id:state.ruleSeq++,name:value('rule-name'),metric:value('rule-metric'),threshold:Number(value('rule-threshold')),active:true});hide();break;
    case 'rule-toggle':{const r=state.rules.find(r=>r.id===Number(id));r.active=!r.active;break}
    case 'rule-delete':dialog('删除规则','<p>停止此规则后续评估，历史触发事实仍保留。</p>',button('确认删除','rule-delete-confirm',id,'danger'));return;
    case 'rule-delete-confirm':state.rules=state.rules.filter(r=>r.id!==Number(id));hide();break;
    case 'evaluate':state.alertFiring=state.rules.some(r=>r.active&&({'P95 延迟':24,'错误数':11,'费用':4.82,'调用量':428}[r.metric]>r.threshold));notify('演示样本已评估，活动状态已更新。');break;
    case 'history-search':state.chainSearch=value('history-search');state.chainMode=value('history-mode');break;
    case 'history-select':state.chainId=id;state.chainSearch=id;state.chainMode='id';break;
    case 'chain-jump':document.getElementById('chain-'+id)?.scrollIntoView({behavior:'auto',block:'start'});return;
    case 'credentials':dialog('编辑演示模型连接','<label>连接显示名称<input id="model-name" placeholder="规划与协作模型"></label><p class="muted">真实产品中填写服务地址、模型名称和凭证；此处仅保存非敏感的演示名称。</p><div class="notice">请勿在原型输入真实凭证。</div>',button('保存并模拟检测','credential-save','','primary'));return;
    case 'credential-save':if(!value('model-name')){fail('请填写连接显示名称。');return}state.credential=true;hide();break;
    case 'account':dialog('创建演示账户',`<label>显示名称<input id="account-name" placeholder="填写审核人名称"></label><label>账户类型<select id="account-role"><option>普通审核人</option><option>管理员</option></select></label><p class="muted">演示不保存密码。正式产品创建账户后仍需授权项目范围。</p>`,button('创建账户','account-save','','primary'));return;
    case 'account-save':if(!value('account-name')){fail('请填写显示名称。');return}if(state.accounts.some(x=>x.split(' · ')[0]===value('account-name'))){fail('已有同名演示账户。');return}state.accounts.push(value('account-name')+' · '+value('account-role'));hide();break;
    case 'setup-prev':state.setup=Math.max(0,state.setup-1);break;
    case 'setup-next':if(state.setup===4){go('issues');notify('配置向导完成 · 演示');return}state.setup++;break;
    case 'local-start':state.localReady=true;notify('4 个本地成员已就绪 · 仅演示，没有启动进程。');break;
    case 'local-stop':dialog('停止本地成员','<p>停止后本地方式无法接受新任务。此处只停止演示状态。</p>',button('确认停止','local-stop-confirm','','danger'));return;
    case 'local-stop-confirm':state.localReady=false;hide();break;
    case 'local-refresh':notify(state.localReady?'演示成员：4 / 4 就绪':'演示成员：尚未启动');return;
    case 'local-guide':dialog('本地成员准备清单','<p>1. 确认已安装受支持的本地智能体工具并完成登录。</p><p>2. 由管理员登记成员、团队和工作范围。</p><p>3. 使用固定启动入口，等待逐成员报告就绪。</p><p>4. 返回需求的开工预览再次核验。</p>');return;
    case 'skill-pass':if(state.skill==='evaluating')state.skillPass=true;else if(state.skill==='canary')state.canaryPass=true;else{notify('请先进入评估或试用阶段。');return}notify('合格评估已记录 · 演示');break;
    case 'skill-fail':if(state.skill==='canary'){state.skill='rolled_back';notify('试用失败，版本已撤回。')}else if(state.skill==='evaluating'){state.skillPass=false;state.skillFailed=true;notify('评估失败，不能晋级；修订后应登记新版本。')}else{notify('当前阶段不能登记评估结果。');return}break;
    case 'skill-next':if(state.skill==='draft')state.skill='evaluating';else if(state.skill==='evaluating'&&state.skillPass&&!state.skillFailed)state.skill='canary';else if(state.skill==='canary'&&state.canaryPass)state.skill='promoted';else{notify('无法晋级：需合格评估，或当前已经终结。');return}break;
    case 'skill-rollback':if(!['canary','promoted'].includes(state.skill)){notify('只有试用或已发布版本可以撤回。');return}state.skill='rolled_back';break;
    case 'ops-save':state.protect=value('protection');notify('运营保护策略已保存 · 演示');break;
    default:notify('该操作未在离线原型中启用。');return;
  }
  render();
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(!el)return;e.preventDefault();act(el.dataset.a,el.dataset.id||'').catch(err=>{notify('演示操作未完成：'+err.message);console.error(err)})});
document.addEventListener('input',e=>{if(e.target.id==='new-body')state.draft=e.target.value;if(e.target.id==='new-title')state.draftTitle=e.target.value});
document.addEventListener('change',async e=>{
  const t=e.target;
  if(t.id==='workspace'){state.workspace=t.value;state.search='';state.tab='open';go('issues');render()}
  if(t.dataset.scope){current().scope[t.dataset.scope]=t.value;current().confirmed=false;render()}
  if(t.id==='usage-days'){state.usageDays=Number(t.value);render()}
  if(t.id==='database-change'){current().database=t.checked;render()}
  if(t.id==='scenario'){
    const i=current();i.stage=t.value;i.analysis=i.stage!=='draft';i.confirmed=i.analysis;i.plan=i.analysis;i.step=['review','delivered','rollback','recovered'].includes(i.stage)?5:i.stage==='running'?1:0;i.approved=i.stage==='delivered';i.paused=false;render();
  }
  if(t.id==='new-file'){
    const file=t.files[0];if(!file)return;if(!/\.(txt|md|markdown)$/i.test(file.name)||file.size>1024*1024){$('#file-note').textContent='请使用不超过 1 MB 的文本或 Markdown 文件。';return}
    const text=await file.text();if(!text.trim()){$('#file-note').textContent='文档没有可用正文。';return}state.draft=text.slice(0,50000);state.draftFile=file.name;$('#new-body').value=state.draft;$('#file-note').textContent=`已解析 ${file.name} · ${state.draft.length} 字符${text.length>50000?' · 超长内容已截断':''}`;
  }
});
document.addEventListener('keydown',e=>{
  if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&$('#dialog').open&&$('#new-body')){e.preventDefault();act('create','')}
  else if(e.key==='Enter'&&!$('#dialog').open){const map={'issue-search':'search','repo-query':'repo-search','log-search':'logs-filter','history-search':'history-search'};if(map[e.target.id])act(map[e.target.id],'')}
});
window.addEventListener('hashchange',()=>{hide();render();window.scrollTo(0,0)});
render();
